"""Toggles whether the nodes of the Structural Analytical Model are shown with SetAnalyticalVisibilitySettings.

Only the given fields change. Reads the setting back and restores it. Requires Archicad 26 or later.
"""
import aclib

settings = aclib.RunTapirCommand ('GetAnalyticalVisibilitySettings', {})['visibilitySettings']

aclib.PrintJson (aclib.RunTapirCommand ('SetAnalyticalVisibilitySettings', {
    'visibilitySettings': {'areNodesVisible': not settings['areNodesVisible']}
}))
aclib.RunTapirCommand ('GetAnalyticalVisibilitySettings', {})

aclib.PrintJson (aclib.RunTapirCommand ('SetAnalyticalVisibilitySettings', {
    'visibilitySettings': {'areNodesVisible': settings['areNodesVisible']}
}))

"""Prints the analytical member type of the first walls, beams and columns of the project with GetAnalyticalMemberTypesOfElements.

Needs at least one wall, beam or column.
"""
import aclib

elements = []
for elementType in ['Wall', 'Beam', 'Column']:
    elements += aclib.RunCommand ('API.GetElementsByType', {'elementType': elementType})['elements'][:2]
if not elements:
    raise SystemExit ('No wall, beam or column in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('GetAnalyticalMemberTypesOfElements', {
    'elements': elements
}))

"""Prints the structural analysis load cases of the first load group of the project with GetAnalyticalLoadCases.

Leave out 'loadGroupId' to get every load case of the project. Needs at least one load group.
"""
import aclib

loadGroups = [g for g in aclib.RunTapirCommand ('GetAnalyticalLoadGroups', {})['loadGroups'] if 'error' not in g]
if not loadGroups:
    raise SystemExit ('No load group in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('GetAnalyticalLoadCases', {
    'loadGroupId': loadGroups[0]['loadGroupId']
}))

"""Creates a permanent and a variable structural analysis load group with CreateAnalyticalLoadGroups.

Every run adds two new load groups.
"""
import aclib

aclib.PrintJson (aclib.RunTapirCommand ('CreateAnalyticalLoadGroups', {
    'loadGroups': [
        {'name': 'Tapir Permanent', 'groupType': 'PermanentLoad', 'relation': 'StandardRelation'},
        {'name': 'Tapir Variable', 'groupType': 'VariableLoad', 'relation': 'StandardRelation'}
    ]
}))

"""Creates a new load group with a dead load case using CreateAnalyticalLoadCases.

Every run adds a new load group and load case.
"""
import aclib

loadGroupId = aclib.RunTapirCommand ('CreateAnalyticalLoadGroups', {
    'loadGroups': [{'name': 'Tapir Permanent', 'groupType': 'PermanentLoad', 'relation': 'StandardRelation'}]
})['loadGroupIds'][0]['loadGroupId']

aclib.PrintJson (aclib.RunTapirCommand ('CreateAnalyticalLoadCases', {
    'loadCases': [{
        'name': 'Tapir Dead Load',
        'description': 'Created by Tapir',
        'actionType': 'PermanentAction',
        'loadGroupId': loadGroupId,
        'loadType': 'StaticLoad',
        'duration': 'LongDuration'
    }]
}))

"""Creates an ultimate limit state load combination of the first load case of the project with CreateAnalyticalLoadCombinations.

Needs at least one load case. Every run adds a new load combination. The combination type requires Archicad 27 or later.
"""
import aclib

loadCases = [c for c in aclib.RunTapirCommand ('GetAnalyticalLoadCases', {})['loadCases'] if 'error' not in c]
if not loadCases:
    raise SystemExit ('No load case in the project.')

aclib.PrintJson (aclib.RunTapirCommand ('CreateAnalyticalLoadCombinations', {
    'loadCombinations': [{
        'name': 'Tapir ULS',
        'category': 'ULS',
        'type': 'Linear',
        'loadFactors': [{'loadCaseId': loadCases[0]['loadCaseId'], 'factor': 1.35, 'multiplier': 1.0}]
    }]
}))

